import{z as B,x as n,o as e,c as P,q as r,j as s,D as E,d as t,s as l,S as o,b as A}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"MPTCP","description":"","frontmatter":{"title":"MPTCP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mptcp.md","filePath":"cs/mptcp.md","lastUpdated":1791413859000}'),p={name:"cs/mptcp.md"};function D(C,a,S,d,T,c){const i=n("Mermaid");return e(),P("div",null,[a[2]||(a[2]=r('<h1 id="mptcp" tabindex="-1">MPTCP <a class="header-anchor" href="#mptcp" aria-label="Permalink to &quot;MPTCP&quot;">​</a></h1><div class="epigraph"><p>一条逻辑 TCP 绑多条子流，各走不同地址或路径；应用仍看见一条字节流，调度在子流间搬数据。</p><footer>—— 据 RFC 8684 MPTCP；Raiciu et al., SIGCOMM 2011 整理</footer></div><p><a href="/cs/tso-lro">TSO</a> 结束单路径细节。主干仍是单四元组。<a href="/cs/tso-lro">上一课</a> 不解决 Wi‑Fi+蜂窝同时用。缺口是 <strong>MPTCP</strong>：子流、令牌、耦合拥塞。本课不把 SCTP 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手机有 WLAN 与 LTE 两地址，单 TCP 只能钉一条。MPTCP：主子流握手后再 ADD_ADDR 开子流，DSS 映射到数据级序号。拥塞：若各子流独立 AIMD，会在共享瓶颈偷两份——要耦合（如 LIA）。中间盒若剥 MPTCP 选项则回退普通 TCP。与 LACP/ECMP：那些是跳内哈希；MPTCP 是端到端多路径。</p><p><span class="marginnote">「偷两份」用数字看：若 Wi‑Fi 与蜂窝子流在运营商侧汇入同一条 10 Mbps 出口，独立 AIMD 会让两条子流各抢一份窗口，合计拿到约两倍公平份额；耦合算法把整体当一条 TCP 对外竞争，内部再分——多径是吞吐冗余，不是抢占外人的杠杆。</span></p><p>不要把 MPTCP 写成 QUIC 迁移的拷贝，下一课对照。</p><p><span class="marginnote">RFC 8684。部署受 NAT 与 API 限制。本课不把每种调度器（minRTT 等）写完。</span></p><h3 id="一条逻辑字节流" tabindex="-1">一条逻辑字节流 <a class="header-anchor" href="#一条逻辑字节流" aria-label="Permalink to &quot;一条逻辑字节流&quot;">​</a></h3><p>子流可走 Wi‑Fi 与蜂窝。拥塞要耦合，防共享瓶颈加倍。中间剥选项则回退 TCP。ADD_ADDR 要令牌。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：应用套接字 → 逻辑连接 → 子流 A/B。对照 SCTP 多宿：SCTP 是另一协议，MPTCP 兼容 TCP 应用。</p>',12)),(e(),s(o,null,{default:E(()=>[l(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E4%B8%80%E6%9D%A1%E5%AD%97%E8%8A%82%E6%B5%81%22%5D%20--%3E%20MP%5B%22MPTCP%20%E6%98%A0%E5%B0%84%22%5D%0A%20%20MP%20--%3E%20S1%5B%22%E5%AD%90%E6%B5%81%20Wi-Fi%22%5D%0A%20%20MP%20--%3E%20S2%5B%22%E5%AD%90%E6%B5%81%20%E8%9C%82%E7%AA%9D%22%5D%0A%20%20CC%5B%22%E8%80%A6%E5%90%88%E6%8B%A5%E5%A1%9E%22%5D%20--%3E%20S1%0A%20%20CC%20--%3E%20S2%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[t("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"BDP 是各子流之和，窗口缩放每子流协商。RPKI 与路径无关。半开保活要每子流或逻辑层。数据中心 ECMP 已多路径，MPTCP 再开可能过度。无线 TCP 后课的误码在子流间可避开坏口。",-1)),a[5]||(a[5]=A("p",null,"安全：ADD_ADDR 要令牌，防劫持子流。",-1)),(e(),s(o,null,{default:E(()=>[l(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEND%5B%22%E5%BA%94%E7%94%A8%E5%86%99%E4%B8%80%E6%AE%B5%E5%AD%97%E8%8A%82%22%5D%20--%3E%20SCHED%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%E6%8C%91%E5%AD%90%E6%B5%81%E5%8F%91%E9%80%81%22%5D%0A%20%20SCHED%20--%3E%20SA%5B%22%E5%AD%90%E6%B5%81A%20%E7%94%A8%E8%87%AA%E5%B7%B1%E7%9A%84%E5%BA%8F%E5%8F%B7%201000-1999%22%5D%0A%20%20SCHED%20--%3E%20SB%5B%22%E5%AD%90%E6%B5%81B%20%E7%94%A8%E8%87%AA%E5%B7%B1%E7%9A%84%E5%BA%8F%E5%8F%B7%20500-999%22%5D%0A%20%20SA%20--%3E%20DSSA%5B%22DSS%20%E9%80%89%E9%A1%B9%3A%20%E6%A0%87%E6%B3%A8%E6%95%B0%E6%8D%AE%E7%BA%A7%E5%BA%8F%E5%8F%B7%200-999%22%5D%0A%20%20SB%20--%3E%20DSSB%5B%22DSS%20%E9%80%89%E9%A1%B9%3A%20%E6%A0%87%E6%B3%A8%E6%95%B0%E6%8D%AE%E7%BA%A7%E5%BA%8F%E5%8F%B7%201000%2B%22%5D%0A%20%20DSSA%20--%3E%20REASS%5B%22%E6%8E%A5%E6%94%B6%E7%AB%AF%E6%8C%89%E6%95%B0%E6%8D%AE%E7%BA%A7%E5%BA%8F%E5%8F%B7%E9%87%8D%E7%BB%84%22%5D%0A%20%20DSSB%20--%3E%20REASS%0A%20%20REASS%20--%3E%20APP2%5B%22%E4%BA%A4%E7%BB%99%E5%BA%94%E7%94%A8%3A%20%E4%B8%80%E6%9D%A1%E6%97%A0%E7%BC%9D%E5%AD%97%E8%8A%82%E6%B5%81%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">DSS（Data Sequence Signal，数据级序号）就是给每段数据再编一套「全局流水号」：子流自己的序号只管本路可靠传输，DSS 才告诉对端这段字节在整条逻辑流里的位置。没有它，Wi‑Fi 上先发的数据被蜂窝后到的数据插队时，接收端无从重排。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MP-QUIC 的全部。SCTP 对照是下一课。后课默认：MPTCP 把多径对应用隐藏为一条 TCP。</p><p>内核/库未开则应用无感也无益。</p><p><span class="marginnote">初学者容易把 MPTCP 想成「更稳的 Wi‑Fi 切换工具」。实际上子流可以<strong>同时</strong>活跃并发数据，不只是坏了一条换另一条的备胎；反过来，两端内核或中间盒只要有一处不支持，它就悄悄退化成普通单路径 TCP——应用从头到尾都察觉不到这个降级。</span></p><p>下一课<a href="/cs/sctp">SCTP 对照</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多子流一条逻辑字节流。</li><li>拥塞要耦合，防共享瓶颈加倍。</li><li>中间盒可能迫使回退。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 8684；Raiciu et al., 2011。</li></ul>',8))])}const u=B(p,[["render",D]]);export{h as __pageData,u as default};
